(()=>{
 const layout=document.querySelector('.layout'),defaults={left:260,right:245,timeline:300},handles=[...document.querySelectorAll('[data-resize]')];let sizes={...defaults},drag=null;
 try{const saved=JSON.parse(localStorage.getItem('tapshop-video-panel-layout')||'null');if(saved)for(const key of Object.keys(defaults))if(Number.isFinite(saved[key]))sizes[key]=saved[key]}catch{}
 function bounds(){let r=layout.getBoundingClientRect();return {width:r.width,height:r.height}}
 function clamp(value,min,max){return Math.max(min,Math.min(max,value))}
 function apply(preferred){if(matchMedia('(max-width:750px)').matches)return;let b=bounds(),available=Math.max(360,b.width-256);sizes.left=clamp(sizes.left,160,Math.min(560,available-160));sizes.right=clamp(sizes.right,160,Math.min(560,available-160));if(sizes.left+sizes.right>available){if(preferred==='right')sizes.left=Math.max(160,available-sizes.right);else sizes.right=Math.max(160,available-sizes.left)}sizes.timeline=clamp(sizes.timeline,140,Math.max(140,b.height-188));layout.style.setProperty('--media-width',sizes.left+'px');layout.style.setProperty('--inspector-width',sizes.right+'px');layout.style.setProperty('--timeline-height',sizes.timeline+'px');handles.forEach(h=>{let key=h.dataset.resize;h.setAttribute('aria-valuemin',key==='timeline'?'140':'160');h.setAttribute('aria-valuemax',String(Math.floor(key==='timeline'?Math.max(140,b.height-188):Math.min(560,available-160))));h.setAttribute('aria-valuenow',String(Math.round(sizes[key])));h.setAttribute('aria-valuetext',Math.round(sizes[key])+' pixels')})}
 function save(){try{localStorage.setItem('tapshop-video-panel-layout',JSON.stringify(sizes))}catch{}}
 function stop(e){if(!drag)return;drag.handle.classList.remove('dragging');document.body.classList.remove('resizing-panels','resize-timeline');drag=null;save()}
 for(const handle of handles){const key=handle.dataset.resize;handle.addEventListener('pointerdown',e=>{if(e.button!==0)return;e.preventDefault();drag={key,handle,x:e.clientX,y:e.clientY,start:sizes[key]};handle.setPointerCapture(e.pointerId);handle.classList.add('dragging');document.body.classList.add('resizing-panels');document.body.classList.toggle('resize-timeline',key==='timeline')});handle.addEventListener('pointermove',e=>{if(!drag||drag.handle!==handle)return;let delta=key==='timeline'?drag.y-e.clientY:key==='right'?drag.x-e.clientX:e.clientX-drag.x;sizes[key]=drag.start+delta;apply(key)});handle.addEventListener('pointerup',stop);handle.addEventListener('pointercancel',stop);handle.addEventListener('lostpointercapture',stop);handle.addEventListener('dblclick',()=>{sizes[key]=defaults[key];apply(key);save()});handle.addEventListener('keydown',e=>{let d=e.shiftKey?40:10;if(key==='timeline'){if(e.key==='ArrowUp')sizes[key]+=d;else if(e.key==='ArrowDown')sizes[key]-=d;else return}else{if(e.key==='ArrowRight')sizes[key]+=key==='left'?d:-d;else if(e.key==='ArrowLeft')sizes[key]+=key==='left'?-d:d;else return}e.preventDefault();apply(key);save()})}
 window.resetPanelLayout=()=>{sizes={...defaults};apply();save()};window.addEventListener('resize',()=>apply());apply();
})();
